        self.val = val
        self.left = left
        self.right = right

class Solution:
    def flatten(self, root):
        nodes=[]
        def pre(node):
            if not node: return
            nodes.append(node); pre(node.left); pre(node.right)
        pre(root)
        for i,node in enumerate(nodes):
            node.left=None
            node.right = nodes[i+1] if i+1 < len(nodes) else None

