class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def flatten(self, root):
        prev=None
        def dfs(node):
            nonlocal prev
            if not node: return
            dfs(node.right); dfs(node.left)
            node.right=prev; node.left=None; prev=node
        dfs(root)

