class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def flatten(self, root):
        cur=root
        while cur:
            if cur.left:
                pred=cur.left
                while pred.right: pred=pred.right
                pred.right=cur.right
                cur.right=cur.left
                cur.left=None
            cur=cur.right

